    while(T--){
        int N; string S; cin>>N>>S;
        long long ans = 0;
        long long cur = 1;
        for(int i = 1; i < N; ++i){
            if(S[i-1] <= S[i]) cur++;
            else { ans += cur*(cur+1)/2; cur = 1; }
        }
        ans += cur*(cur+1)/2;
